	private List<String> rows(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> result = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			return result.stream()
					.map(LmdbAdjacencySemijoinTest::canonical)
					.sorted()
					.collect(Collectors.toList());
		}
	}

	private static String canonical(BindingSet bindings) {
		return bindings.getBindingNames()
				.stream()
				.sorted()
				.filter(name -> bindings.getValue(name) != null)
				.map(name -> name + "=" + bindings.getValue(name))
				.collect(Collectors.joining(";", "[", "]"));
	}

	private static String q(String body) {
		return "PREFIX ex: <" + EX + ">\n" + body;
	}

	private void assertAllModesAgree(String query) {
		System.setProperty(NATIVE_FLAG, "false");
		List<String> generic = rows(query);
		assertThat(generic).as("fixture must produce rows for:\n" + query).isNotEmpty();
		System.setProperty(NATIVE_FLAG, "true");
		System.setProperty(SEMIJOIN_FLAG, "false");
		assertThat(rows(query)).as("native (semijoin off) vs generic for:\n" + query).isEqualTo(generic);
		System.setProperty(SEMIJOIN_FLAG, "true");
		assertThat(rows(query)).as("native (semijoin on) vs generic for:\n" + query).isEqualTo(generic);
	}

	@ParameterizedTest
	@ValueSource(strings = {
			// EXISTS, constant object: one cached incoming run, per-row lowerBound
			"SELECT ?a ?b WHERE { ?a ex:knows ?b . FILTER EXISTS { ?b ex:knows ex:person0 } }",
			// NOT EXISTS over the same shape
			"SELECT ?a ?b WHERE { ?a ex:knows ?b . FILTER NOT EXISTS { ?b ex:knows ex:person0 } }",
			// EXISTS, bound key with free neighbor: run-presence answer
			"SELECT ?a ?b WHERE { ?a ex:knows ?b . FILTER EXISTS { ?b ex:nick ?n } }",
			// EXISTS, both endpoints row-bound: doubly-bound lowerBound check
			"SELECT ?a ?b WHERE { ?a ex:knows ?b . FILTER EXISTS { ?b ex:knows ?a } }",
			// EXISTS, incoming plane presence (free subject)
			"SELECT ?a ?b WHERE { ?a ex:knows ?b . FILTER EXISTS { ?x ex:knows ?b } }",
			// MINUS, constant object
			"SELECT ?a ?b WHERE { ?a ex:knows ?b MINUS { ?b ex:based_near ex:oslo } }",
			// MINUS, free object
			"SELECT ?a ?b WHERE { ?a ex:knows ?b MINUS { ?b ex:nick ?n } }",
			// context-scoped EXISTS: the adjacency probe must decline, results must stay exact
			"SELECT ?a ?b WHERE { ?a ex:knows ?b . FILTER EXISTS { GRAPH ex:g1 { ?b ex:knows ?x } } }",
			// fully-constant EXISTS
			"SELECT ?a WHERE { ?a ex:based_near ex:oslo . FILTER EXISTS { ex:person7 ex:knows ex:person0 } }" })
	void semijoinModesAgree(String body) {
		assertAllModesAgree(q(body));
	}

	@Test
	void existsConstantObjectServedByAdjacency() {
		System.setProperty(NATIVE_FLAG, "true");
		System.setProperty(SEMIJOIN_FLAG, "true");
		long answeredBefore = JoinDispatchTestAccess.adjacencySemijoinAnswered();
		long runProbesBefore = JoinDispatchTestAccess.adjacencySemijoinRunProbes();
		List<String> result = rows(
				q("SELECT ?a ?b WHERE { ?a ex:knows ?b . FILTER EXISTS { ?b ex:knows ex:person0 } }"));
		assertThat(result).isNotEmpty();
		assertThat(JoinDispatchTestAccess.adjacencySemijoinAnswered())
				.as("EXISTS verdicts must be served by the adjacency semijoin probe")
				.isGreaterThan(answeredBefore);
		assertThat(JoinDispatchTestAccess.adjacencySemijoinRunProbes())
				.as("the constant-key case must gallop inside one cached run")
				.isGreaterThan(runProbesBefore);
	}

